  CollectionHall_117989_Desc = {
    Text = "Несчастный, дерзкий, не знающий своей силы волк.\nОн был выброшен в отдыхательную комнату вместе с другими гостями, в ходе короткой спокойной игры на удачу.\nПотеряв привычную удачу, он проиграл более десяти тысяч рео."
