  CollectionHall_121154_Title = {Text = "Лай"},
  CollectionHall_121341_Desc = {
    Text = "<Title:Описание>\nПринявшая ответственность за беременность «Святого дитя» «Принцесса», ныне является ключевой «Богоматерью» в церкви Мореплавателей.\nОна когда-то была дамой, устремившейся к свободе, и ушла в бегство на «Сонаниле», как и Митхаг, записавшая мёрфи.\nНо в мире без Хранителей Колесо Судьбы сломала изящную шейку юного лебедя.\nПерепутанная кровь, не подлежащая сопротивлению, мучительно запутывала её, даже если оставить тело умирать, она не могла избежать.\nОна из последних сил произносит снова и снова «Я благородная Богоматерь», все лишь для самоподсознания и убеждения.\nОсталось лишь повиновение, только повиновение. Повиновение ложному оракулу, повиновение абсурдной судьбе, и затем из бесконечного горечи едва ли пробуждается тот сладковатый блаженства в фантазии."
  },
  CollectionHall_121341_LockTip = {
    Text = "Разблокируется после пробуждения «Мёрфи: Лжерождённая»"
  },
  CollectionHall_121341_Title = {
    Text = "Мёрфи: Лжерождённая"
  },
  CollectionHall_121381_Desc = {
    Text = "Ты обменял тысячу желудеек на одну историю из другого мира.\nИстория о героях и богах, о наблюдении и стойкости.\nИстория о безысходности и нежелании, о старых и новых друзьях.\nИстория, которая когда-то была."
  },
  CollectionHall_121381_LockTip = {
    Text = "Завершить многомерное соединение «мой ход»"
  },
  CollectionHall_121381_Title = {
    Text = "Эхо гостиницы всевозможного мира"
  },
  CollectionHall_121382_Desc = {
    Text = "Долгие века спустя он и он наконец стали героями, о которых слагали песни.\nО искуплении по ту сторону смерти, о близнецах из одной души."
  },
  CollectionHall_121382_LockTip = {
    Text = "Завершите Сонный пейзаж «За гранью небес·Вниз»"
  },
  CollectionHall_121382_Title = {
    Text = "Стих о безкрылой птице"
  },
  CollectionHall_121383_Desc = {
    Text = "Молодой человек за кратковременные вещи заплатил цену, которую надо было взыскать.\nТеперь осталась только безмолвная Независимый, чтобы быть с ним.\nКороль собирается уснуть, он встречает Конец мира во сне."
  },
  CollectionHall_121383_LockTip = {
    Text = "Завершить Погружение в сознание «День коронации»"
  },
  CollectionHall_121383_Title = {
    Text = "Земля нескончаемых страданий"
  },
  CollectionHall_121384_Desc = {
    Text = "Они окружают тебя, они восхищаются тобой, они сопровождают тебя. \nОни поднимают парус перед Творцом."
  },
  CollectionHall_121384_LockTip = {
    Text = "Завершить расследование 9-11 для разблокировки"
  },
  CollectionHall_121384_Title = {
    Text = "Состояние ветра к богу-творцу"
  },
  CollectionHall_121385_Desc = {
    Text = "Это были крылья, возрожденные в разрушении, это были крылья, которые приобрели свободу через жертву.\nПророчество судьбы уже сбылось, он поклялся в горьком раскаянии, что кровный долг будет возмещен кровью."
  },
  CollectionHall_121385_LockTip = {
    Text = "Завершите Сонный пейзаж «За гранью небес·Вниз»"
  },
  CollectionHall_121385_Title = {
    Text = "Когда поднимается буря"
  },
  CollectionHall_121386_Desc = {
    Text = "В абсурдных и хаотичных сновидениях, в самом начале, Он определенно столкнется со своей судьбой.\nНо Он уже испытал слишком много и определил слишком многое.\nОн решил с максимальной разумностью, которую может сохранить человек, наблюдать за своим истоком, этим высшим божеством."
  },
  CollectionHall_121386_LockTip = {
    Text = "Завершить расследование 9-11 для разблокировки"
  },
  CollectionHall_121386_Title = {
    Text = "Битва первобытной судьбы"
  },
  CollectionHall_121387_Desc = {
    Text = "Получить, потерять, Разрыв, пожертвовать.\nГерой заплатил всю цену, и Независимый защищать сокровища — это его награда."
  },
  CollectionHall_121387_LockTip = {
    Text = "Завершить расследование 9-13 для разблокировки"
  },
  CollectionHall_121387_Title = {
    Text = "Слепой глаз"
  },
  CollectionHall_121388_Desc = {
    Text = "Он возложил корону на себя, он наложил на себя кандалы.\nЭто было мимолетное, обманчивое тепло, это был благой Погоня за светом, предначертанный к уничтожению."
  },
  CollectionHall_121388_LockTip = {
    Text = "Завершить Погружение в сознание «День коронации»"
  },
  CollectionHall_121388_Title = {
    Text = "Одинокий путь младшего короля"
  },
  CollectionHall_121389_Desc = {
    Text = "Несмотря на неблагоприятные обстоятельства, твой уголок губ уже слегка приподнят.\n«Мой ход, тяну карту!»\nНе стоит недооценивать способности помощи, когда дело касается урона! Игнатийс!"
  },
  CollectionHall_121389_LockTip = {
    Text = "Завершить многомерное соединение «мой ход»"
  },
  CollectionHall_121389_Title = {
    Text = "Мой момент переворота!"
  },
  CollectionHall_121390_Desc = {
    Text = "Целая легенда не может быть без превращения врагов в друзей."
  },
  CollectionHall_121390_LockTip = {
