  },
  CollectionHall_121390_Title = {
    Text = "Враги, друзья"
  },
  CollectionHall_121391_Desc = {
    Text = "С этого момента ты будешь носить титул Хранителя тайн и будешь вместе с тысячами и тысячами учителей и учеников Мисаг."
  },
  CollectionHall_121391_LockTip = {
    Text = "Завершить расследование·Трудный 9-11 для разблокировки"
  },
  CollectionHall_121392_Desc = {
    Text = "Мы, возможно, мгновение в вечности, песчинки в буре.\nНо вечность — это наше ценное, так как, несмотря на все безумие мира —\nДостоинство человека зиждется на свете разума."
  },
  CollectionHall_121392_LockTip = {
    Text = "Завершить расследование 9-11 для разблокировки"
  },
  CollectionHall_121392_Title = {
    Text = "Вечное воздание"
  },
  CollectionHall_121393_Desc = {
    Text = "Герои бросились в сказку, каждая сказка одинакова: животные, демоны, феи и неизвестные миры.\nПересекая мимолетную свободу и ложные желания, в конце сказки скрыта подделанная сердце, навязанное ему."
  },
  CollectionHall_121393_LockTip = {
    Text = "Завершите Сонный пейзаж «За гранью небес·Вниз»"
  },
  CollectionHall_121393_Title = {
    Text = "Влетая в звездное море"
  },
  CollectionHall_121394_Desc = {
    Text = "Здесь находится окна Отель Вселенной, расположенное в пространственном разрыве и внезависимости от реального мира.\nСвязывая разные вселенные, сверкая бескрайним светом звёзд, приветствуя тебя.\nПодожди… для чего это нужно Хранителю?"
  },
  CollectionHall_121394_LockTip = {
    Text = "Завершить многомерное соединение «мой ход»"
  },
  CollectionHall_121394_Title = {
    Text = "Добро пожаловать в отель «Вселенная»!"
  },
  CollectionHall_121395_Desc = {
    Text = "Клинок Митхага принесёт тебе победу в этой игре.\nСвязь между тобой и спутником непоколебима.\nДаже если вы окажетесь в разных вселенных, это невозможно изменить."
  },
  CollectionHall_121395_LockTip = {
    Text = "Завершить многомерное соединение «мой ход»"
  },
  CollectionHall_121395_Title = {
    Text = "Клинок мисага!"
  },
  CollectionHall_121396_Desc = {
    Text = "«Ежедневный квест не прошёл? Не лучше ли сыграть партию в универсальные карты?»\n«Региональный d-Эффект не активировал? Не лучше ли сыграть партию в универсальные карты?»\n«Это фазовая ловушка, а не универсальные карты! Тысяча желуде́й, я соберу их для тебя на показ!»"
  },
  CollectionHall_121396_LockTip = {
    Text = "Завершить многомерное соединение «мой ход»"
  },
  CollectionHall_121396_Title = {
    Text = "Давай играть в карты всевозможных форм!"
  },
  CollectionHall_121397_Desc = {
    Text = "Позови меня по имени, прежде чем пред рассветной зарей."
