  CollectionHall_131664_Desc = {
    Text = "Позвольте мне подумать, о чем же рассказать сегодня...\nАх, я поняла, история для маленькой леди и маленьких господ будет такой ~ в полночь не говорите о совести, в три часа ночи душа обиженного поднимается на перекладину."
