  CollectionHall_131668_Desc = {
    Text = "Странное, странное, мертвая жена вылезает из земли в три часа ночи, бездушный сын варит в котле. \n Божественная Матушка без формы, желающая спасти страдающих, разрежет лицо и раздвинет грудь, чтобы взять кости любимого, и принесет их перед моим великим господом."
  },
  CollectionHall_131668_LockTip = {
    Text = "Пройдено сознательного плавания «Шёпот из-за веера»"
  },
  CollectionHall_131668_Title = {
