  CollectionHall_131669_Desc = {
    Text = "Максимум, что может произойти — ты её порежешь, она тебя убьёт, и вы вместе отправитесь на тот Погоня за светом, как пара призраков. \n Не переживай, не стоит волноваться."
  },
