  CollectionHall_133769_Title = {
    Text = "Погружение"
  },
  CollectionHall_133770_Desc = {
    Text = "Уважаемые пассажиры, добрый день!\nПраздник Цисуй уже совсем близко. В этот прекрасный момент воссоединения семей и встречи Нового года весь персонал поезда выражает вам, преодолевшим долгий путь домой и уставшим в дороге, самые искренние пожелания —\nСчастливого праздника Цисуй, Радости в кругу семьи, стремительного пути и исполнения всех желаний! <(￣︶￣)↗[GO!]"
  },
  CollectionHall_133770_LockTip = {
    Text = "Завершена оперативная запись«Поезд в праздник Весенний фестиваль»"
  },
  CollectionHall_133770_Title = {
    Text = "Мчимся вперёд: экспресс Радости"
  },
  CollectionHall_133771_Desc = {
    Text = "Уважаемые пассажиры, добрый день. С сожалением сообщаем вам, что в связи с личным настроением машиниста поезд радости совершает временную остановку. О точном времени отправления мы объявим по громкой связи сразу после окончания взаимного истребления.\nВо время стоянки кондиционер, освещение и туалеты работают в штатном режиме. Просим пользоваться ими по мере необходимости в зависимости от потребностей в убийстве, чтобы не допустить отсутствия опасности.\nВедь долг поезда радости — дарить улыбку каждому пассажиру～(￣▽￣～)(～￣▽￣)～"
  },
  CollectionHall_133771_LockTip = {
    Text = "Завершена оперативная запись«Поезд в праздник Весенний фестиваль»"
  },
  CollectionHall_133771_Title = {
    Text = "Экстренное торможение!"
  },
  CollectionHall_133772_Desc = {
    Text = "Внимание: следующая остановка — Древняя страна дракона спирали. Пассажиров, выходящих в Древней стране дракона спирали, просим заблаговременно освоить технику исполнения песни «Какой прекрасный жасмин».\nПотому что у вас уже не будет возможности выйти φ(≧ω≦*)♪"
  },
  CollectionHall_133772_LockTip = {
    Text = "Завершена оперативная запись«Поезд в праздник Весенний фестиваль»"
  },
  CollectionHall_133772_Title = {
