  CollectionHall_134293_Desc = {
    Text = "<Title:Введение>\nВладелица Театра судьбы, автор пьес, актриса, вечная Ткачиха судеб и вечный пленник...\nС момента своего рождения Арахна обладала способностью видеть ниточки судьбы. Используя веретено под названием «Мойрай», она постоянно ткет судьбы для мира, поддерживая хрупкий Баланс судьбы. Для этого она изгнала все свои красоты и хрупкость, чтобы сделать самые правильные выборы для всех судеб, взяв на себя всю ответственность за судьбы.\nОна давно знала, что в конце сети судьбы Упокоение неизбежно. Но она все равно без усталости продолжала ткет, наблюдая, как все, что она любила, медленно падает в ту точку, где все исчезает.\nОна ткет, ждет, ждет ту нить, которую никогда не предсказывала, что спасет сеть судьбы из глубин."
  },
  CollectionHall_134293_LockTip = {
    Text = "Пробудить «Арахна» после разблокировки"
  },
  CollectionHall_134293_Title = {
    Text = "Арахна"
  },
  CollectionHall_134294_LockTip = {
    Text = "Разблокируется после прохождения этапа 5-16 Расследования – Звёздное Царство"
