  CollectionHall_147988_Desc = {
    Text = "Убери свою никчёмную корону — я никогда не обращал на неё внимания. Обнажи клинок, мир охвачен жаждой крови!\nТак и только так —\nУбивай! Пожирай! Гибни!"
  },
  CollectionHall_147988_LockTip = {
    Text = "Завершить Погружение в сознание «Пока не грянет китопад»"
  },
  CollectionHall_147988_Title = {
    Text = "Безумный танец, разящий небеса"
  },
  CollectionHall_147989_Desc = {
    Text = "В те времена я был ничтожнейшим из слуг и своими глазами видел поход, который иначе как жестоким не назовёшь.\nТа легендарная госпожа — сила была отлита в её костях и крови, горячая кровь пылала негасимым огнём, а огонь зажигал её глаза —\nЗапомни же эту историю вместо меня, дитя моё. …В конце концов она победила и покорила звёздное небо."
  },
