  CollectionHall_48635_Desc = {
    Text = "<Title:Краткое описание>\nМисага, исполняющая обязанности декана.\nУченица Краули Макиннон, младшая сестра Герберта по учению.\nОдна из свидетелей убийства наставника Гербертом; после смерти преподавателя продолжила вести дела академии.\nУбежденный сторонник эффективности, никогда не опаздывает; короткая стрижка помогает экономить время на укладку.\nИз-за войны бежала из родной Эльк в Лео.\nНе может полностью согнуть указательный палец правой руки, что, предположительно, является следствием жестокого обращения в концентрационном лагере."
  },
