  CollectionHall_51019_Desc = {
    Text = "<Title:Дата основания>\nДо Накопления\n\n<Title:Основатель>\nНеизвестно\n\n<Title:Обзор>\nКочевые народы, отделившиеся от Ассирийской империи.\nСкрываются в вечных сильных бурях пустыни Ремуахе, ведут крайне примитивный образ жизни и редко общаются с внешним миром. Аланы верят в «Материнское древо урожая», полагаясь на аномальные способности к размножению материнского дерева и воды Священной реки для поддержания численности населения.\nПосле операции «Ремуахе» Арамиты исчезли без следа, больше не было никаких известий."
  },
  CollectionHall_51019_LockTip = {
    Text = "Разблокируется после прохождения расследовательской операции главы 7 «Река желаний»"
  },
  CollectionHall_51019_Title = {Text = "Аланы"},
  CollectionHall_51038_Title = {
    Text = "07желанная река"
  },
  CollectionHall_51373_Title = {
    Text = "Непостижимое"
  },
  CollectionHall_51374_Desc = {
    Text = "<Title:Краткое описание>\nПрофессор Университета Мисаг, общественный деятель, аристократ.\nРаньше был расточительным повесой, совершил несколько безобидных преступлений и пользовался известностью как в криминальных, так и в легальных кругах.\nПозже его семья была уничтожена адептами секты, он стал единственным выжившим. Что произошло после этого, знает только он сам.\nХотя является приёмным отцом Рамоны, он хранит молчание о её происхождении.\nВ молодости не сдал ни одного экзамена, но затем неожиданно стал профессором Мисаг.\nБыл известен своей свободной и независимой натурой, однако никогда не было слухов о его связях с женщинами или мужчинами.\nВ общем, это человек, полный противоречий."
  },
  CollectionHall_51374_LockTip = {
    Text = "Прохождение пролога для разблокировки"
  },
  CollectionHall_51374_Title = {
    Text = "Декстер"
  },
  CollectionHall_51375_Desc = {
    Text = "<Title:Краткое описание>\nПриемная дочь Декстера, самый надежный партнер главного героя в расследованиях.\nС ранних лет проводила время в аудиториях разных факультетов академии, обладает глубокими знаниями о феномене растворения, пробуждающих телах и других явлениях.\n\nВ юном возрасте Рамона иногда мечтала о «биологических родителях», но благодаря заботе Декстера и преподавателей она давно считает академию своим настоящим домом.\n\nХладнокровие, рациональность и умеренная доброта делают её абсолютно не «странной» — на фоне группы эксцентричных личностей Мисаг её «нормальность» выделяется ещё сильнее.\nНесмотря на постоянное серьёзное выражение лица, те, кто знает её близко, понимают, что это лишь усталость от жизни «гения»."
  },
