  CollectionHall_61045_Title = {
    Text = "A moll: Конечная симфония"
  },
  CollectionHall_62183_Title = {
    Text = "08 Финальная симфония"
  },
  CollectionHall_62184_Desc = {
    Text = "<Title:Краткое описание>\nВсемирно известный Дирижёр и музыкант. Несмотря на юный возраст, симфонические концерты под его управлением уже объездили весь мир, и каждое выступление собирало огромное количество зрителей.\nКак самый знаменитый гений в мире классической музыки, любая личная информация о Хамлине остаётся неизвестной, что привлекло внимание рассмотрения дела. В ходе длительного расследования они обнаружили, что места выступлений Хамлина совпадают с траекторией действий Церкви Фонаря.\nПрежде чем они нашли правду, Правда сама нашла их — в ходе инцидента с нападением Церкви Фонаря на Мисагу, Хамлин сыграл очень важную роль.\nИменно тогда люди осознали, что настоящая сцена этого гениального дирижёра всегда была за пределами театра."
  },
  CollectionHall_62184_LockTip = {
    Text = "Разблокируется после прохождения расследовательской операции главы 8 «Финальная симфония»"
  },
  CollectionHall_62184_Title = {
