  CollectionHall_65509_Desc = {
    Text = "<Title:Краткое описание>\nМелкий хулиган из Восточного района, а также сестра «24». \nОбладает тремя уникальными навыками: воровством, перепалками и умением быстро убегать при первой опасности. \nНикто не может получить выгоду от неё. \nАх да, у неё есть мышка по имени «Браун», которая всегда рядом. \nБраун спокойный и уравновешенный, что хорошо дополняет характер Дженкинс. \nПоэтому, даже несмотря на то, что в Восточном районе Лондиниум голодные люди часто готовят мышей, Дженкинс никогда не думала об этом."
