  CollectionHall_71028_Desc = {
    Text = "Правила музея восковых фигур состоят из трех пунктов: первое, не надо прикасаться к восковым фигурам; второе, не надо снимать покрывала с восковых фигур; Часть 3, не надо проливать кровь в музее. Пожалуйста, ни в коем случае не нарушайте их."
