  },
  CollectionHall_89418_Desc = {
    Text = "Поиграй со мной в игру, не переживай, не так опасно, просто чтобы отнять это скучное время."
  },
  CollectionHall_89418_LockTip = {
    Text = "Завершить Погружение в сознание«потомки бледных»"
