  CollectionHall_89418_Title = {
    Text = "Игра в отгадывание"
  },
  CollectionHall_89419_Desc = {
    Text = "Светящиеся приливы морей, ведомые небесными телами, сплетаются в Занавес опускается, чудовища, ступающие в море, идут по волнам."
  },
  CollectionHall_89419_LockTip = {
    Text = "Завершите операцию расследования 5-15 для разблокировки"
  },
  CollectionHall_89419_Title = {
    Text = "Иллюзорные морские приливы"
  },
  CollectionHall_89420_Desc = {
    Text = "Царь всевластен, царская Независимый безгранична, царь одиноко взирает с блестящей высоты на своё царство."
  },
  CollectionHall_89420_LockTip = {
    Text = "Завершите операцию расследования 5-15 для разблокировки"
  },
  CollectionHall_89420_Title = {
    Text = "Спящий под владыкой бездны"
  },
  CollectionHall_89706_Desc = {
    Text = "<Title:Описание>\nСирота, с неизвестным происхождением, с самого начала своей памяти был взят на борт командой и жил на корабле. \nИз-за такого опыта Кеперсант с детства был наполнен жаждой и любопытством к морю. \nКогда она выросла, она естественно выбрала профессию, связанную с морем и кораблями — штурман. \nС тех пор девушка, любящая море, вечного блуждает по морю, под звездами, указывая курс корабля. \nОна «родилась» в море, на корабле. \nОна также не боится «умереть» на море, на корабле. \nВот такова ее жизнь."
  },
  CollectionHall_89706_LockTip = {
    Text = "Очнувшись «Коперсанта» разблокирует"
  },
  CollectionHall_89706_Title = {
    Text = "Корпосант"
  },
  CollectionHall_89968_Desc = {
    Text = "Убийство, Досаждение, безумие и страдания, на поле битвы всегда этих хватает. Когда ты ставишь жизнь на карту в игре с монстрами, следует подумать, к какому кровавому вихрю это приведет."
  },
  CollectionHall_89968_LockTip = {
    Text = "Завершить Вдаль от берегов в сознание«Кровь и Песок»"
  },
  CollectionHall_89968_Title = {
    Text = "Алая воронка"
  },
  CollectionHall_89969_Desc = {
    Text = "По легенде, после смерти штурман превращается в синий и белый Погоня за светом на мачте, продолжая указывать путь кораблю.\nКогда она зажгла свою жизнь на вершине мачты, увидела ли она ту надежду возвращения?"
  },
  CollectionHall_89969_LockTip = {
    Text = "Завершите сознательный скиталец «Последний штурман»."
  },
  CollectionHall_89969_Title = {
    Text = "Святое пламя Эльмора"
  },
  CollectionHall_89970_Desc = {
    Text = "Ее Колесо Судьбы с рождения наполнена ненавистью, убийствами и бесконечными битвами.\nКогда она отвергает все мягкие и теплые иллюзии и выбирает взять в руки нож и пистолет, победный гимн судьбы уже звучит для нее.\nОна предназначена стать воином, смывая Досаждение кровью врага, прожив, возможно, не славную, но бесстрашную и без сожалений жизнь."
  },
  CollectionHall_89970_LockTip = {
    Text = "Завершить оперативную запись «Возвращенец из Элвортса»"
  },
  CollectionHall_89970_Title = {
    Text = "Убить врагов в крови"
  },
  CollectionHall_89971_Desc = {
    Text = "Под кроваво-красным закатом лежит жёлтый песок, пропитанный кровью.\nСамый сильный воин стоит на поле боя, которое скоро поглотит ночь, вспоминая золотые огни и славу былых времён.\nТысячи кричащих стервятников взмывают в воздух, закрывая последние лучи солнца. Под величественным крестовым походом лишь толпы нежити заполняют пустыню, прощаясь с ним."
  },
  CollectionHall_89971_LockTip = {
    Text = "Завершите Погружение в сознание «Кровь и Песок»в сложном режиме"
  },
  CollectionHall_89971_Title = {
    Text = "Кровавое солнце"
  },
  CollectionHall_89972_Desc = {
    Text = "Если этот мир погружен во тьму, то я стану последним светом.\nЕсли среди людей больше нет справедливости, то я выступлю за самых слабых."
  },
  CollectionHall_89972_LockTip = {
    Text = "Завершите сознательный скиталец «Последний штурман»."
  },
  CollectionHall_89972_Title = {
    Text = "Долго ночь Искра факела"
  },
  CollectionHall_89973_Desc = {
    Text = "Это была её судьбоносная битва, это было поле боя, на которое она должна была выдвинуться.\nОна оставила все трусость, колебания и Страх в прошлом.\nОна не сожалеет, потому что поняла настоящую суть боевых действий в этой жизни.\nОна не одна, в отражении лезвия её меча видно совершенно другое, неистовое лицо."
  },
  CollectionHall_89973_LockTip = {
    Text = "Завершите Оперативную запись «Возвращенец из Элворт» на сложности"
  },
  CollectionHall_89973_Title = {
    Text = "Задайте вопросы горам"
  },
  CollectionHall_89974_Desc = {
    Text = "Эй-йо, эй-йо, поднимайте якорь, поднимайте паруса, развязывайте последние канаты.\nНаш штурман уже влез на мачту, яркие флаги высоко развеваются.\nВперёд, вперёд, по направлению, что она указывает, мы должны отправляться!"
  },
  CollectionHall_89974_LockTip = {
    Text = "Завершите сознательный скиталец «Последний штурман»."
  },
  CollectionHall_89974_Title = {
    Text = "Записки штурмана"
  },
  CollectionHall_89975_Desc = {
    Text = "Каждый раз перед отплытием она готовит новое завещание.\nЭта песня, передаваемая через поколения, как колыбельная из сна, нежно обнимает ее душу.\nЯркие флаги развеваются на ветру, ее тело может разрушиться, разложиться, утонуть в глубоком море, но ее душа будет стоять на корабле, испуская вечный Погоня за светом к звездам и морю."
  },
  CollectionHall_89975_LockTip = {
    Text = "Завершите сознательный скиталец «Последний штурман»."
  },
  CollectionHall_89975_Title = {
    Text = "Песня навигатора"
  },
  CollectionHall_89976_Desc = {
    Text = "В пустыне Куси ветер и песок являются постоянными спутниками, зависая в воздухе песчинки могут затечь в рот и нос живого человека, а также похоронить мертвые, безымянные тела.\nТолько жаждущие крови существа будут осторожно нюхать сладкий аромат этого угощения."
  },
  CollectionHall_89976_LockTip = {
    Text = "Завершить Вдаль от берегов в сознание«Кровь и Песок»"
  },
  CollectionHall_89976_Title = {
    Text = "Жёлтый песок и звери"
  },
  CollectionHall_89977_Desc = {
    Text = "Солнце в пустыне отличается от других мест, оно бледное, ослепительное и жестокое, у него никогда не было мягкой стороны. Дикие звери не могут представить себе весну, которую ты описываешь, тогда дай ему взглянуть на это так называемое настоящее солнце."
  },
  CollectionHall_89977_LockTip = {
    Text = "Завершить Вдаль от берегов в сознание«Кровь и Песок»"
  },
  CollectionHall_89977_Title = {
    Text = "Кровь и песок без возврата"
  },
  CollectionHall_89978_Desc = {
    Text = "Снег неумолимо падает, покрывая воина белой изморозью.\nВоспоминания всей её жизни текут в этот момент, она проходит через глубину души, чтобы отправиться в величественные горы.\nПредательство, оставление и защита, вся боль и Негодование – это лишь битвы одна за другой. С людьми, с горами, с собой.\nОна смотрит на своего руководителя, на новых, ещё незнакомых, но уже родных товарищей и улыбка неуверенно появляется на её лице.\nОна однажды может вернуться с победой, или вечно лежать на поле битвы, но даже завоёвав царство бога или пав в ад, она не отпустит меч в своей руке.\nЧтобы не потерять всё, она на этот раз выбирает защиту, поднимает меч охраны и отправляется в своё сражение одна."
  },
  CollectionHall_89978_LockTip = {
    Text = "Завершить оперативную запись «Возвращенец из Элвортса»"
  },
  CollectionHall_89978_Title = {
    Text = "Чтобы больше не терять завтра"
  },
  CollectionHall_89998_LockTip = {
    Text = "Требуется пройти любую миссию ограниченного времени «Тени, вглядывающиеся в божественное царство: Необычные приливы»"
  },
  CollectionHall_89998_Title = {
    Text = "Наблюдая за Царством бога из тени: Аномальная морская волна"
  },
  CollectionHall_89999_LockTip = {
    Text = "Требуется пройти любое из ограниченных по времени испытаний «Узник зеркал: Прыжок в голубое небо»"
  },
  CollectionHall_89999_Title = {
    Text = "Узник зеркал: Прыжок в голубое небо"
  },
  CollectionHall_90245_LockTip = {
    Text = "Прохождение Сонного пейзажа «за горизонт» первая задача разблокирована"
  },
  CollectionHall_90245_Title = {
    Text = "Когда птица еще не упала"
  },
  CollectionHall_90415_Title = {
    Text = "За гранью небес·Вверх"
  },
  CollectionHall_90416_Desc = {
    Text = "<Title:Описание>\nОдин из серии экспериментов, выращенных Церковью светлого храма для церемонии призывания божества. Благодаря счастливому рождению как близнец, избежал участи быть выброшенным на свалку.\nС раннего возраста воспитывался в качестве священного дитя вместе с братом Поллуксом, испытывал строгую дисциплину, ежедневно подвергался внушению теология о носителе светильника, единственная информация о внешнем мире - это великий рукописный том, предложенный верующими.\nВ юности, после жестокой хирургической модификации, проведенной церковью брату, они решили бежать вместе в поисках свободы, но вскоре были пойманы.\nОн погружен в растворяющий пруд под названием «Озеро греха», использовал «Греховную терапию» для лечения ран, перенес затяжные мучения.\nВ результате все, кроме Жюльетты, забыли о нем, включая Поллукса, и их отношения стали напряженными.\nС тех пор он затаился, притворившись послушным церкви, в душе никогда не отказывался от намерения снова сбежать с братом, всегда ожидая возможности вновь обрести свободу."
  },
  CollectionHall_90416_LockTip = {
    Text = "Разблокируется после пробуждения «Кастора»"
  },
  CollectionHall_90416_Title = {
    Text = "Кастор"
  },
  CollectionHall_94552_LockTip = {
    Text = "Необходимо пройти любое задание ограниченного времени «Великое завоевание: Священная охота»"
  },
  CollectionHall_94552_Title = {
    Text = "Великие завоевания: священная охота"
  },
  CollectionHall_94553_Desc = {
    Text = "<Title:Введение>\nИскусственные близнецы, созданные Церковью Фонаря для ритуала призыва божеств, разделились из плоти старшего брата в момент, когда их признали неудачными экспериментами и собирались жестоко выбросить.\nТакое стремление к жизни не было удачей, а изменило судьбы двоих из короткой трагедии на более длинную трагедию.\nВозможно, исходя из тайны двойственности, его цвет кожи и характер были совершенно противоположны брату. Будучи более живым и сообразительным из близнецов, он всегда совершал непослушные поступки, напоминая озорного мальчишку из обычной семьи — до тех пор, пока его не выбрали в качестве сосуда для божественности и не начали регулярно подвергать мучительным и кровавым ритуалам «священной трансформации».\nНе в силах вынести боль и безнадежную судьбу, братья втайне планировали несколько лет, и наконец, преодолев множество преград, им удалось сбежать.\nОднако они не успели порадоваться, как были пойманы преследователями церкви. По приказу Лиетт у него отобрали крылья свободы и подвергли жестокой промывке мозгов, в результате чего он полностью забыл о брате и стал наслаждаться ощущением, что он святой сын, которого все восхваляют.\nЛишь после Часть 2 попытки побега, когда он вспомнил о брате и смерти, а также о ритуале призыва божеств, его «святое сердце» разгорелось ненавистью и гневом, и он принял решение противостоять Церкви Фонаря как новое направление в жизни."
  },
  CollectionHall_94553_LockTip = {
    Text = "Прохождение «Сонный пейзаж» «За гранью небес·Низ» разблокировано"
  },
  CollectionHall_94553_Title = {
    Text = "Поллукс"
  },
  CollectionHall_95436_Desc = {
    Text = "Лети, лети, птица использует свои крылья, чтобы противостоять тяжёлой силе притяжения, постоянно поднимаясь, поднимаясь, проходя через потоки и водовороты, взмывая всё выше и выше. \nОднако он не осознает, что на его ногах есть невидимая нить, он, возможно, никогда не стал настоящей птицей, даже если он летит, он просто жалкий воздушный змей. \nСейчас нить от воздушного змея натянулась."
  },
  CollectionHall_95436_LockTip = {
    Text = "Закончите «За гранью небес·Часть 1» в сонном пейзаже"
  },
  CollectionHall_95436_Title = {
    Text = "Воздушный змей"
  },
  CollectionHall_95437_Desc = {
    Text = "Ты увидел то лицо, нежное, спокойное, красивое лицо.\nОно быстро растворилось в твоей памяти, но ты все равно будешь помнить цвет мягкого света зари после долгого ночного дождя."
  },
  CollectionHall_95437_LockTip = {
    Text = "Завершить оперативную запись «Призрак дождливого города»"
  },
  CollectionHall_95437_Title = {
    Text = "В глубине дождевого занавеса"
  },
  CollectionHall_95438_Desc = {
    Text = "Будь котом, беззаботным котом, оставайся только с любимыми, каждый день свертывайся возле неё и грейся на солнце.\nЭто её маленькая мечта в глубине сердца, но мечты всегда были такими хрупкими и ломкими."
  },
  CollectionHall_95438_LockTip = {
    Text = "Завершить оперативную запись «Тихая фрагментация»"
  },
  CollectionHall_95438_Title = {
    Text = "Желание Кошки"
  },
  CollectionHall_95439_Desc = {
    Text = "Даже если мир рассыплется в прах, даже если все будет пропитано D-слизью, невинная медуза может вечно погружаться в свои иллюзии.\nТам все как прежде. Только смех. Только радость."
  },
  CollectionHall_95439_LockTip = {
    Text = "Завершите Погружение в сознание «всё идёт как обычно»на сложности трудная"
  },
  CollectionHall_95439_Title = {
    Text = "Погружение в безумие и хаос"
  },
  CollectionHall_95440_Desc = {
    Text = "Зима в Лондиниуме не часто бывает снежной, и каждый раз, когда идет снег, это вызывает восторженное веселье у детей.\nТы просыпаешься после нежного долгого сна и протягиваешь руку к окну. Снежинка падает тебе на ладонь и с радостью тает в тепле.\nКружась, снежинки, совершив короткое путешествие по небу, возвращаются на землю, возвращаются к темной реке, возвращаются к домам и перерождению всех капель воды.\nВ первый снег этой зимы еще одна она вернулась домой.\nСпокойной ночи, снег; спокойной ночи, «24»."
  },
  CollectionHall_95440_LockTip = {
    Text = "Завершить оперативную запись «Тихая фрагментация»"
  },
  CollectionHall_95440_Title = {
    Text = "Спокойной ночи, Снег"
  },
  CollectionHall_95441_Desc = {
    Text = "Белый коралл разрастался в ветви, вырастая в чисто-белый дворец.\nВ деформированных колоннах разноцветные рыбки свободно плавали.\nТело тонет, душа парит.\nВы охотно теряете дыхание, погружаясь с ней, погружаясь, погружаясь в белый сон.\nЭто чудо моря, это теплая синяя родина."
  },
  CollectionHall_95441_LockTip = {
    Text = "Завершить Погружение в сознание «Резьба, звучащая песней»"
  },
  CollectionHall_95441_Title = {
    Text = "Чисто-белый дворец"
  },
  CollectionHall_95442_Desc = {
    Text = "Тик-так — маленький поезд отправляется!\nПозволь мне взять с собой друзей в королевство счастливой сказки, где нет страданий."
  },
  CollectionHall_95442_LockTip = {
    Text = "Завершить Погружение в сознание «всё идёт как обычно»"
  },
  CollectionHall_95442_Title = {
    Text = "Наивные мечты"
  },
  CollectionHall_95443_Desc = {
    Text = "Она Ассасин? Она как будто твоя возлюбленная, с которой ты много лет не виделся.\nДождь, высохшие листья и легкий цветочный аромат, ты шевелишь ноздри, пытаясь уловить хоть каплю крови из тех влажных запахов, чтобы подтвердить её вину. Но ты ничего не почувствовал.\nОна даже не пыталась объяснить, в туманной мгле ты погружаешься в её серый сон."
  },
  CollectionHall_95443_LockTip = {
    Text = "Завершить оперативную запись «Призрак дождливого города»"
  },
  CollectionHall_95443_Title = {
    Text = "Подозреваемый"
  },
  CollectionHall_95444_Desc = {
    Text = "Тоже самое жажда, которую она когда-то испытывала.\nНевежество, зверство и одиночество.\nЕй повезло, она завершила долгие странствия и обладает теплыми воспоминаниями, которые можно пережевывать всю жизнь.\nСейчас она берет за руку своих сородичей, отправляя эту блуждающую душу в тихий сон."
  },
  CollectionHall_95444_LockTip = {
    Text = "Завершить оперативную запись «Призрак дождливого города» на высокой сложности"
  },
  CollectionHall_95444_Title = {
    Text = "Сон зверя"
  },
  CollectionHall_95445_Desc = {
    Text = "Из моего острия, вонзающегося в моё сердце.\nПеред безжалостной судьбой и горькой жизнью я так мал, слаб и беспомощен.\nНа что я имею право быть собой? Я готов ли к тому, чтобы быть собой?\nИз моего вопроса, я тоже не могу ответить."
  },
  CollectionHall_95445_LockTip = {
    Text = "Завершить оперативную запись «Тихая фрагментация»"
  },
  CollectionHall_95445_Title = {
    Text = "Спроси меня"
  },
  CollectionHall_95446_Desc = {
    Text = "Хм? Ты как будто стал другим? \nСтали глаза светлее? Стали движения более живыми? Или в этом заурядном теле уже поменялся Носитель души?"
  },
  CollectionHall_95446_LockTip = {
    Text = "Завершить Погружение в сознание «Резьба, звучащая песней»"
  },
  CollectionHall_95446_Title = {
    Text = "Перемещение души."
  },
  CollectionHall_95447_Desc = {
    Text = "Независимо от того, идет ли снег, дождь, солнечный день или пасмурный, в сегодняшней реке вода продолжает тихо течь."
  },
  CollectionHall_95447_LockTip = {
    Text = "Завершить оперативную запись «Тихая фрагментация»"
  },
  CollectionHall_95447_Title = {
    Text = "Спокойная река"
  },
  CollectionHall_95448_Desc = {
    Text = "Прилив несется, головы остро кричат.\nТысяч глаз впиваются в тебя, множество уст громко осуждают тебя.\nОни хотят тебя поглотить, они хотят тебя поглотить.\nТы в страхе закрываешь глаза, и когда открываешь их снова, ты понимаешь, что они прямо рядом с тобой."
  },
  CollectionHall_95448_LockTip = {
    Text = "Завершить оперативную запись «Призрак дождливого города»"
  },
  CollectionHall_95448_Title = {
    Text = "Морская голова"
  },
  CollectionHall_95449_Desc = {
    Text = "Она обещала тебе, что обязательно приведет тебя домой.\n——С вечной позой вернуться в тихую, полную чудес и красоты родину."
  },
  CollectionHall_95449_LockTip = {
    Text = "Завершить Погружение в сознание «Резьба, звучащая песней»"
  },
  CollectionHall_95449_Title = {
    Text = "Петроглифика"
  },
  CollectionHall_95450_Desc = {
    Text = "Тот благородный Гость смотрел на спину Кастора, полной надежды, и под луной шептал предсказание судьбы: «Он выйдет наружу, он будет бороться в бурю. То, что поднимет его высоко, также приведёт к падению»"
  },
  CollectionHall_95450_LockTip = {
    Text = "Закончите «За гранью небес·Часть 1» в сонном пейзаже"
  },
  CollectionHall_95450_Title = {
    Text = "В буре"
  },
  CollectionHall_95451_Desc = {
    Text = "Рождённая в красоте, умершая в красоте.\nОна гений, сумасшедшая, дьявол, она безразличный Палач, а также ваша заботливая семья.\nОна с горячей любовью создает из вас совершенное произведение.\nОна обнимает вас и берет ваши холодные руки. Она возьмет вас и вернёт вас в родину искусства вместе с ней."
  },
  CollectionHall_95451_LockTip = {
    Text = "Завершите Погружение в сознание «Как песня высекаемая в камне» на сложности трудный Уровень"
  },
  CollectionHall_95451_Title = {
    Text = "Красивая смерть"
  },
  CollectionHall_95452_Desc = {
    Text = "Море услышало мой зов и привело тебя ко мне.\nС этого момента мы можем свободно говорить, играть и веселиться, стали самыми лучшими друзьями в мире.\nВ этом полном растворении мертвом городе."
  },
  CollectionHall_95452_LockTip = {
    Text = "Завершить Погружение в сознание «всё идёт как обычно»"
  },
  CollectionHall_95452_Title = {
    Text = "Пожалуйста, станьте моим другом"
  },
  CollectionHall_95453_Desc = {
    Text = "Возвращайся, все смелые, трусливые, умные, глупые, сильные, слабые я.\nПусть все радостные, печальные, гневные, мучительные, уставшие сердца растопятся.\nМы вместе.\nОни навсегда вместе."
  },
  CollectionHall_95453_LockTip = {
    Text = "Завершите оперативную запись «Тихая фрагментация» на высокой сложности"
  },
  CollectionHall_95453_Title = {
    Text = "Вернуться к ней"
  },
  CollectionHall_95454_Desc = {
    Text = "Это пустота и трещины души может заполнить только самая чистая сказка.\nВ один прекрасный день она попрощается с болью и вернётся в наполнённый радостью «родной дом»."
  },
  CollectionHall_95454_LockTip = {
    Text = "Завершить Погружение в сознание «всё идёт как обычно»"
  },
  CollectionHall_95454_Title = {
    Text = "Наивная шокирующая сказка"
  },
  CollectionHall_95455_Desc = {
    Text = "Темные, глубокие и узкие переулки всегда носят множество поворотных моментов судьбы. Воссоединение, ссора, разрыв, даже насилие, травля, убийство.\nК счастью, сегодня история обошлась без кровавых сцен во Часть 2 части, но кто может сказать, что то, что произошло в первой части, не является истинной трагедией?"
  },
  CollectionHall_95455_LockTip = {
    Text = "Закончите «За гранью небес·Часть 1» в сонном пейзаже"
  },
  CollectionHall_95455_Title = {
    Text = "Тёмный переулок"
  },
