  },
  CollectionHall_96790_Title = {
    Text = "Ночной Роскошный Роскошный пир во дворце"
  },
  CollectionHall_97150_LockTip = {
    Text = "Необходимо пройти любую миссию ограниченного времени «Темная сторона холста: Инородная картина»"
  },
  CollectionHall_97150_Title = {
    Text = "Темная сторона холста: свиток из другого мира"
  },
  CollectionHall_97158_LockTip = {
    Text = "Требуется пройти любой этап временного мероприятия «Затмение: Охота за Золой»"
  },
  CollectionHall_97158_Title = {
    Text = "Свет и тьма, падая с небес: истребление охоты"
  },
  CollectionHall_97208_LockTip = {
    Text = "Пройти «Сознательное Скиталец» и разблокировать первый Уровень в «Холст ужаса»"
  },
  CollectionHall_97208_Title = {
