  },
  CollectionHall_97736_LockTip = {
    Text = "Необходимо пройти любой Уровень временного события «Праздник рождения богов: Создание семи дней»"
  },
  CollectionHall_97736_Title = {
    Text = "Свиток иного мира"
  },
  CollectionHall_97896_LockTip = {
    Text = "Необходимо пройти временное мероприятие «Если все как обычно: Новые дела на солнечном свете» на любом уровне"
  },
  CollectionHall_97896_Title = {
    Text = "Если б жизнь была как прежде"
  },
  CollectionHall_98502_LockTip = {
    Text = "Разблокировать первый Уровень после прохождения «Сознательного плавания: Неугасимый полярный день»"
  },
  CollectionHall_98502_Title = {
    Text = "Вечная охота неугасимого"
  },
  CollectionHall_98636_Desc = {
    Text = "Богохульник поднимает темно-синюю волну, хрупкий король одинокий противостоит гигантской волне в тысячу метров.\n Его волосы развеваются на ветру, его кости и кровь являются его торжественным объявлением, в презрительной улыбке он посвящает себя смерти и луне.\n Так вся морская стихия замерла в этот момент, висячие ледники остановились под полной луной, все вернулось к тишине, все спокойствие вернулось в его царство."
  },
  CollectionHall_98636_LockTip = {
    Text = "Завершите расследование·Трудный Операция Звезды глава 3-10 разблокирована"
  },
  CollectionHall_98636_Title = {
    Text = "Полная лунная церемония"
  },
  CollectionHall_98637_Desc = {
    Text = "Приготовление мертвых – это серьезное искусство.\nОн использует нож и лопату, чтобы узнать незаконченные слова, он использует воду и Искра, чтобы удовлетворить последние желания.\nКаждое неловкое, болезненное, кислое воспоминание станет сверкающим и ароматным произведением искусства, которое можно будет наслаждаться и хранить."
  },
  CollectionHall_98637_LockTip = {
    Text = "Завершите расследование Операция Звезды глава 3-11 разблокирована"
  },
  CollectionHall_98637_Title = {
    Text = "Носитель обеденного стола"
  },
  CollectionHall_98638_Desc = {
    Text = "Дети плачут, кричат и ведут себя неразумно.\nОн есть центр вселенной, он есть всё это место.\nОн хочет, чтобы всё, что можно увидеть, окружало, подчинялось и возносило ему."
  },
  CollectionHall_98638_LockTip = {
    Text = "Завершите Операцию расследования·Трудный 6-10 для разблокировки"
  },
  CollectionHall_98638_Title = {
    Text = "Рождение бога"
  },
  CollectionHall_98639_Desc = {
    Text = "Он не только безжалостно размахивал косой, собирая каждую смерть.\nОн тоже когда-то имел теплые руки, когда-то имел чувствительное сердце.\nКогда он вкусил печаль той души, он тоже расплакался.\nКогда он познал ту острую Досаждение, он будет вместо этого приносить Трибунал.\nОн обещал от имени господина похорон: все, кто оскверняет смерть, исчезнут в ледяном густом тумане."
  },
  CollectionHall_98639_LockTip = {
    Text = "Завершите расследование Операция Звезды глава 3-11 разблокирована"
  },
  CollectionHall_98639_Title = {
    Text = "Взор смерти"
  },
  CollectionHall_98640_Desc = {
    Text = "Вкус кровавого мяса и сладостной тяжести сражения его самые знакомые и незабываемые воспоминания.\nОн давно понял, что этот город мертвецов продолжает существовать не благодаря силе живых, а благодаря жертве мертвых.\nЕще одна капля ярко-красного проглатывается горлом, он закрывает глаза и тщательно наслаждается каждым различным ароматом, запоминая вкус каждой души, таким образом его родные и подданные живут в его теле вечно.\nОни договорились быть вместе навсегда."
  },
  CollectionHall_98640_LockTip = {
    Text = "Завершите расследование·Трудный Операция Звезды глава 3-10 разблокирована"
  },
  CollectionHall_98640_Title = {
    Text = "Кровавый договор"
  },
  CollectionHall_98641_Desc = {
    Text = "Ритуальный нож при лунном свете сверкает привлекательным светом.\nОна доказала свою мечту о свободной воле через решительную смерть."
  },
  CollectionHall_98641_LockTip = {
    Text = "Завершите Операцию расследования 6-15 для разблокировки"
  },
  CollectionHall_98641_Title = {
    Text = "Холодный лунный Погоня за светом"
  },
  CollectionHall_98642_Desc = {
    Text = "Он обучал своих соплеменников, как сражаться, как убивать, как выживать, но никогда не учил, как сбежать, когда сталкиваешься с противником, числом превосходящим в несколько раз.  \nПоэтому он тоже не сбежит.\nВсего лишь голова, берите!  \nОн давно понял: амбициозный человек, стремящийся к силе, погибает в погоне — это лишь предопределенная Колесо Судьбы."
  },
  CollectionHall_98642_LockTip = {
    Text = "Завершить Погружение в сознание *Падение гиганта*"
  },
  CollectionHall_98642_Title = {
    Text = "Я не боюсь смерти"
  },
  CollectionHall_98643_Desc = {
    Text = "Хруст, хруст.\nБог раскрыл рот, радостно приняв всю преданность верующего и самого верующего."
  },
  CollectionHall_98643_LockTip = {
    Text = "Завершите Операцию расследования 6-15 для разблокировки"
  },
  CollectionHall_98643_Title = {
    Text = "Первое блюдо"
  },
  CollectionHall_98644_Desc = {
    Text = "Когда-то к моему народу бросилась Орден разбухшей благодати, намереваясь задушить их поверженного и изгнанного вождя. А не самый яростный Босс в истории филистимлян, обладающий непокоримой волей, ответил на это убийством.\nВ безконечных вскриках, огромный клинок жадно пьёт кровь, истолковывая его стиль боя — деспотичный, дерзкий, жестокий и варварский.\nНе нужно жалости к врагам.\nОни просто необходимые ступени, чтобы занять опять вершину власти."
  },
  CollectionHall_98644_LockTip = {
    Text = "Завершить Погружение в сознание *Падение гиганта*"
  },
  CollectionHall_98644_Title = {
    Text = "Необходимые убийства"
  },
  CollectionHall_98645_Desc = {
    Text = "В момент, когда он повернулся и ушел, Эльтон снова стал тем мальчиком, который только что вышел в море, с небом и бескрайним океаном, соединёнными вместе, мир оказался таким большим, что вмещает все устремления и мечты.\nИное дело, что на этот раз он уже ясно видел, как выглядят сбывшиеся мечты, и у него есть дорога к той стране с белыми птицами, в страну грез."
  },
  CollectionHall_98645_LockTip = {
    Text = "Завершите Операцию расследования·Трудный 6-10 для разблокировки"
  },
  CollectionHall_98645_Title = {
    Text = "Родина белых птиц"
  },
  CollectionHall_98646_Desc = {
    Text = "Время пришло, серебряная луна высоко в небе.\nПоскорее поднимай жесткие пальцы, этой ночью мы будем наслаждаться временем банкета.\nОна подошла к последнему этапу, а мы провожаем ее своим желудком.\nПо кусочку тебе, по кусочку мне, с этого момента никто не забудет."
  },
  CollectionHall_98646_LockTip = {
    Text = "Завершите расследование Операция Звезды глава 3-11 разблокирована"
  },
  CollectionHall_98646_Title = {
    Text = "Танец умерших"
  },
  CollectionHall_98647_Desc = {
    Text = "Если чудо имело бы форму, то оно было бы похоже на её сложенные вместе руки.\n Если божество имело бы облик, то это было бы как её спокойное лицо."
  },
  CollectionHall_98647_LockTip = {
    Text = "Завершите Операцию расследования 6-15 для разблокировки"
  },
  CollectionHall_98647_Title = {
    Text = "Чистая белая богиня"
  },
  CollectionHall_98648_Desc = {
    Text = "Празднуй, мой Близкий Близкий друг♪\nКости под лунным светом тихо распускаются, дорогой любимый подаётся на блюде♪\nВсе Гость уже пришли! Пойте, танцуйте♪\nМы никогда не молимся за мертвецов, мы никогда не скорбим по трупам♪\nОна передала мне память, она передала мне слёзы♪\nДавайте проглотим её душу и плоть♪\nНа пиршестве смерти мы снова будем вместе♪"
  },
  CollectionHall_98648_LockTip = {
    Text = "Завершите расследование Операция Звезды глава 3-11 разблокирована"
  },
  CollectionHall_98648_Title = {
    Text = "Песня каннибала"
  },
  CollectionHall_98649_Desc = {
    Text = "Люди боятся его силы, восхищаются им, из-за его жестокости ненавидят его, презирают его, а из-за его неудачи насмехаются над ним, изгоняют его.\nНо жалкие крики слабых ничего не значат, взгляд гиганта останавливается только на сильных.\nВ безлюдном море изгнания он ставит свою жизнь на кон, отправляясь на поиски абсолютной силы."
  },
  CollectionHall_98649_LockTip = {
    Text = "Завершить Погружение в сознание *Падение гиганта*"
  },
  CollectionHall_98649_Title = {
    Text = "Отправляясь в новое путешествие"
  },
  CollectionHall_98650_Desc = {
    Text = "Он помнил о ней. \nО той девочке, которую он крепко держал в пеленках в бурю, в конечном итоге отправленной им же в бездну — чтобы обменять с ней свой совести за тот мечта о белой птице, летящей высоко. \nОн надеялся, что красивый сон его жизни сбудется, и теперь пора расплатиться за все черные грехи остальной жизни."
  },
  CollectionHall_98650_LockTip = {
    Text = "Завершите Операцию расследования 6-15 для разблокировки"
  },
  CollectionHall_98650_Title = {
    Text = "Вернуться долга"
  },
  CollectionHall_98651_Desc = {
    Text = "Разлука и смерть — это неизбежность в этом мире.\nВыходя из множества жертв и смертей, идете к неясному будущему, легкая грусть окутывает твоё сердце. Однако увидев людей, живущих в смерти, и увидев короля, который дарует смерти мягкий финал, ты больше не боишься неизвестного конца.\nФиалковая незабудка упала на плечо, прощая его с далеких расстояний.\nТы знаешь, что вне зависимости от обстоятельств, путь назад не будет одиноким."
  },
  CollectionHall_98651_LockTip = {
